-- The snapshot has no rating-version field; convert existing five-point values once.
UPDATE "DiscoveryState" SET state = jsonb_set(jsonb_set(state, '{ratings}', COALESCE((SELECT jsonb_object_agg(key, to_jsonb((value::text)::integer * 2)) FROM jsonb_each(COALESCE(state->'ratings', '{}'::jsonb))), '{}'::jsonb)), '{history}', COALESCE((SELECT jsonb_agg(CASE WHEN entry->>'decision' = 'seen' AND entry ? 'rating' THEN jsonb_set(entry, '{rating}', to_jsonb((entry->>'rating')::integer * 2)) ELSE entry END ORDER BY ord) FROM jsonb_array_elements(COALESCE(state->'history', '[]'::jsonb)) WITH ORDINALITY AS h(entry, ord)), '[]'::jsonb)), revision = revision + 1;
